    // ==========================================
    // 10. THU THẬP VÀ XỬ LÝ HÌNH ẢNH TRONG ĐỀ THI
    // ==========================================
    function getImageDimensions(bytes) {
        if (!bytes || bytes.length < 24) return { w: 400, h: 300 };
        // PNG (Signature: 89 50 4E 47 0D 0A 1A 0A)
        if (bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4E && bytes[3] === 0x47) {
            const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
            const w = dv.getUint32(16, false);
            const h = dv.getUint32(20, false);
            return { w: w || 400, h: h || 300 };
        }
        // JPEG (SOI: FF D8)
        if (bytes[0] === 0xFF && bytes[1] === 0xD8) {
            let i = 2;
            while (i < bytes.length - 8) {
                if (bytes[i] === 0xFF) {
                    const marker = bytes[i + 1];
                    if (marker === 0xC0 || marker === 0xC2) { // SOF0, SOF2
                        const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
                        const h = dv.getUint16(i + 5, false);
                        const w = dv.getUint16(i + 7, false);
                        return { w: w || 400, h: h || 300 };
                    }
                    const len = (bytes[i + 2] << 8) | bytes[i + 3];
                    i += 2 + len;
                } else {
                    i++;
                }
            }
        }
        // GIF (GIF87a or GIF89a)
        if (bytes[0] === 0x47 && bytes[1] === 0x49 && bytes[2] === 0x46) {
            const w = bytes[6] | (bytes[7] << 8);
            const h = bytes[8] | (bytes[9] << 8);
            return { w: w || 400, h: h || 300 };
        }
        return { w: 400, h: 300 };
    }

    async function svgToPngBytes(svgText, scale = 2) {
        if (typeof document === 'undefined' || !document || !document.createElement) return null;
        return new Promise((resolve) => {
            try {
                let cleanSvg = String(svgText || '').trim();
                if (!cleanSvg) return resolve(null);
                // Đảm bảo SVG có viewBox hoặc width/height
                if (!/viewBox=/i.test(cleanSvg)) {
                    const wM = cleanSvg.match(/width=["'](\d+(?:\.\d+)?)/i);
                    const hM = cleanSvg.match(/height=["'](\d+(?:\.\d+)?)/i);
                    if (wM && hM) {
                        cleanSvg = cleanSvg.replace(/<svg\b/i, `<svg viewBox="0 0 ${Math.round(parseFloat(wM[1]))} ${Math.round(parseFloat(hM[1]))}" `);
                    }
                }
                const blob = new Blob([cleanSvg], { type: 'image/svg+xml;charset=utf-8' });
                const url = URL.createObjectURL(blob);
                const img = new Image();
                img.onload = () => {
                    try {
                        const canvas = document.createElement('canvas');
                        const nw = img.naturalWidth || 400;
                        const nh = img.naturalHeight || 300;
                        canvas.width = Math.round(nw * scale);
                        canvas.height = Math.round(nh * scale);
                        const ctx = canvas.getContext('2d');
                        ctx.imageSmoothingEnabled = true;
                        ctx.imageSmoothingQuality = 'high';
                        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                        URL.revokeObjectURL(url);
                        canvas.toBlob((pngBlob) => {
                            if (!pngBlob) return resolve(null);
                            const reader = new FileReader();
                            reader.onload = () => resolve(new Uint8Array(reader.result));
                            reader.onerror = () => resolve(null);
                            reader.readAsArrayBuffer(pngBlob);
                        }, 'image/png');
                    } catch(e) {
                        URL.revokeObjectURL(url);
                        resolve(null);
                    }
                };
                img.onerror = () => {
                    URL.revokeObjectURL(url);
                    resolve(null);
                };
                img.src = url;
            } catch(err) {
                resolve(null);
            }
        });
    }

    async function imageToPngBytes(srcUrl) {
        if (typeof document === 'undefined' || !document || !document.createElement) return null;
        return new Promise((resolve) => {
            try {
                const img = new Image();
                img.crossOrigin = 'anonymous';
                const timer = setTimeout(() => resolve(null), 6000);
                img.onload = () => {
                    clearTimeout(timer);
                    try {
                        const canvas = document.createElement('canvas');
                        canvas.width = img.naturalWidth || img.width || 400;
                        canvas.height = img.naturalHeight || img.height || 300;
                        const ctx = canvas.getContext('2d');
                        ctx.drawImage(img, 0, 0);
                        canvas.toBlob((blob) => {
                            if (!blob) return resolve(null);
                            const r = new FileReader();
                            r.onload = () => resolve(new Uint8Array(r.result));
                            r.onerror = () => resolve(null);
                            r.readAsArrayBuffer(blob);
                        }, 'image/png');
                    } catch(e) {
                        resolve(null);
                    }
                };
                img.onerror = () => {
                    clearTimeout(timer);
                    resolve(null);
                };
                img.src = srcUrl;
            } catch(e) {
                resolve(null);
            }
        });
    }

    async function fetchImageBytes(src) {
        if (!src) return null;
        src = String(src).trim();

        // 1. Data URL
        if (src.startsWith('data:image')) {
            try {
                if (src.startsWith('data:image/svg+xml')) {
                    const commaIdx = src.indexOf(',');
                    const svgText = src.includes(';base64,')
                        ? atob(src.substring(commaIdx + 1))
                        : decodeURIComponent(src.substring(commaIdx + 1));
                    const pngBytes = await svgToPngBytes(svgText);
                    if (pngBytes) return pngBytes;
                }
                const base64 = src.split(',')[1];
                const binStr = (typeof atob === 'function')
                    ? atob(base64)
                    : (typeof Buffer !== 'undefined' ? Buffer.from(base64, 'base64').toString('binary') : '');
                if (!binStr) return null;
                const arr = new Uint8Array(binStr.length);
                for (let i = 0; i < binStr.length; i++) arr[i] = binStr.charCodeAt(i);
                return arr;
            } catch (e) {
                console.warn('[ImageLoader] Lỗi decode base64:', e);
                return null;
            }
        }

        // 2. HTTP / HTTPS / Đường dẫn tương đối
        const urlsToTry = [src];
        if (src.startsWith('http://') || src.startsWith('https://')) {
            // Cloudflare R2 bucket hỗ trợ CORS trực tiếp; proxy dự phòng nếu cần
            urlsToTry.push(`https://images.weserv.nl/?url=${encodeURIComponent(src)}`);
            urlsToTry.push(`https://api.allorigins.win/raw?url=${encodeURIComponent(src)}`);
        }

        for (const url of urlsToTry) {
            try {
                const resp = await fetch(url);
                if (resp.ok) {
                    const ct = (resp.headers.get('content-type') || '').toLowerCase();
                    const ab = await resp.arrayBuffer();
                    if (ab && ab.byteLength > 0) {
                        const u8 = new Uint8Array(ab);
                        const snippet = new TextDecoder('utf-8', { fatal: false }).decode(u8.subarray(0, Math.min(250, u8.length)));

                        // Nếu là SVG (từ R2 TikZ render): chuyển đổi sang PNG chuẩn cho Word
                        if (ct.includes('svg') || snippet.includes('<svg') || (snippet.includes('<?xml') && snippet.includes('<svg')) || url.toLowerCase().includes('.svg')) {
                            const fullSvg = new TextDecoder('utf-8').decode(u8);
                            const png = await svgToPngBytes(fullSvg, 2);
                            if (png && png.length > 0) return png;
                        }

                        // Kiểm tra Header nhị phân hợp lệ của ảnh
                        const isPng = u8.length > 8 && u8[0] === 0x89 && u8[1] === 0x50 && u8[2] === 0x4E && u8[3] === 0x47;
                        const isJpg = u8.length > 3 && u8[0] === 0xFF && u8[1] === 0xD8 && u8[2] === 0xFF;
                        const isGif = u8.length > 4 && u8[0] === 0x47 && u8[1] === 0x49 && u8[2] === 0x46;
                        const isWebp = u8.length > 12 && u8[0] === 0x52 && u8[1] === 0x49 && u8[2] === 0x46 && u8[3] === 0x46;

                        if (isPng || isJpg || isGif) {
                            return u8;
                        }
                        if (isWebp) {
                            const converted = await imageToPngBytes(url);
                            if (converted) return converted;
                            return u8;
                        }
                        // Không trả về file HTML lỗi (403/404 HTML text giả dạng ảnh)
                        if (snippet.includes('<html') || snippet.includes('<!doctype') || snippet.includes('Access Denied')) {
                            continue;
                        }
                        return u8;
                    }
                }
            } catch (err) {
                // Thử tiếp proxy dự phòng
            }
        }

        // 3. Fallback Canvas DOM (trường hợp ảnh đã nạp sẵn trong cache trình duyệt)
        try {
            const fallbackU8 = await imageToPngBytes(src);
            if (fallbackU8 && fallbackU8.length > 0) return fallbackU8;
        } catch (domErr) {}

        return null;
    }

    async function collectAndPrepareImages(questions, zip) {
        const imageMap = {};
        let imgCounter = 0;

        const scanTextForImages = (text) => {
            if (!text) return [];
            const matches = [];
            const imgRegex = /<img\s+[^>]*src=["']([^"']+)["'][^>]*>/gi;
            let m;
            while ((m = imgRegex.exec(text)) !== null) {
                matches.push(m[1]);
            }
            const texImgRegex = /\\includegraphics(?:\[.*?\])?\{([^}]+)\}/gi;
            while ((m = texImgRegex.exec(text)) !== null) {
                matches.push(m[1]);
            }
            return matches;
        };

        const scanTextForTikz = (text) => {
            if (!text) return [];
            const matches = [];
            const tikzRegex = /\\begin\{tikzpicture\}[\s\S]*?\\end\{tikzpicture\}/gi;
            let m;
            while ((m = tikzRegex.exec(text)) !== null) {
                matches.push(m[0]);
            }
            return matches;
        };

        const allSources = [];
        const allTikz = [];
        const qList = Array.isArray(questions) ? questions : [];

        qList.forEach(q => {
            if (q.image) allSources.push(q.image);
            if (q.img) allSources.push(q.img);
            if (q.imageUrl) allSources.push(q.imageUrl);
            if (q.image_url) allSources.push(q.image_url);
            if (Array.isArray(q.images)) allSources.push(...q.images);

            allSources.push(...scanTextForImages(q.content));
            allSources.push(...scanTextForImages(q.solution || q.explain));
            allTikz.push(...scanTextForTikz(q.content));
            allTikz.push(...scanTextForTikz(q.solution || q.explain));

            (q.options || []).forEach(opt => {
                if (typeof opt === 'object') {
                    if (opt.image) allSources.push(opt.image);
                    if (opt.img) allSources.push(opt.img);
                }
                const optText = typeof opt === 'object' ? (opt.text || '') : opt;
                allSources.push(...scanTextForImages(optText));
                allTikz.push(...scanTextForTikz(optText));
            });

            (q.statements || []).forEach(st => {
                if (typeof st === 'object') {
                    if (st.image) allSources.push(st.image);
                    if (st.img) allSources.push(st.img);
                }
                const stText = typeof st === 'object' ? (st.content || st.text || '') : st;
                allSources.push(...scanTextForImages(stText));
                allTikz.push(...scanTextForTikz(stText));
            });
        });

        // Tự động biên dịch TikZ nếu có engine TikZ trên window
        const uniqueTikz = Array.from(new Set(allTikz.filter(Boolean)));
        if (uniqueTikz.length > 0 && typeof window !== 'undefined' && typeof window.compileTikZToImage === 'function') {
            for (const tikzCode of uniqueTikz) {
                try {
                    const codeToRun = (typeof window.prepareTikzForCompilation === 'function')
                        ? window.prepareTikzForCompilation(tikzCode)
                        : tikzCode;
                    const renderedUrl = await window.compileTikZToImage(codeToRun);
                    if (renderedUrl && !renderedUrl.includes('Image+Error')) {
                        allSources.push(renderedUrl);
                        // Liên kết cả mã gốc tikzCode với URL ảnh đã render
                        imageMap[tikzCode] = renderedUrl;
                    }
                } catch (tErr) {
                    console.warn('[TikZ Compiler] Lỗi biên dịch TikZ khi xuất Word:', tErr);
                }
            }
        }

        const uniqueSources = Array.from(new Set(allSources.filter(Boolean)));

        for (const src of uniqueSources) {
            try {
                const bytes = await fetchImageBytes(src);
                if (bytes && bytes.length > 0) {
                    imgCounter++;
                    const imgId = imgCounter;
                    const rId = `rIdImg_${imgId}`;

                    // Kích thước hình ảnh giảm tiếp 15% theo yêu cầu của Thầy (~5.8 - 6.0 cm)
                    const dims = getImageDimensions(bytes);
                    const maxW_emu = 2300000; // ~6.0 cm (~2.36 inches, ~51% trang A4)
                    const maxH_emu = 1800000; // ~4.7 cm
                    let cx = Math.round(dims.w * 9525 * 0.51);
                    let cy = Math.round(dims.h * 9525 * 0.51);

                    if (cx > maxW_emu) {
                        const sc = maxW_emu / cx;
                        cx = maxW_emu;
                        cy = Math.round(cy * sc);
                    }
                    if (cy > maxH_emu) {
                        const sc = maxH_emu / cy;
                        cy = maxH_emu;
                        cx = Math.round(cx * sc);
                    }
                    cx = Math.max(600000, cx);  // min ~1.5cm
                    cy = Math.max(450000, cy);  // min ~1.1cm

                    zip.file(`word/media/image_${imgId}.png`, bytes);
                    const imgPayload = { id: imgId, rId, cx, cy };
                    imageMap[src] = imgPayload;

                    // Nếu có mã TikZ trỏ đến URL này, cập nhật cả ánh xạ TikZ
                    for (const [tCode, rUrl] of Object.entries(imageMap)) {
                        if (rUrl === src) {
                            imageMap[tCode] = imgPayload;
                        }
                    }
                }
            } catch (err) {
                console.warn('[ImageLoader] Không thể nạp hình ảnh:', src, err);
            }
        }

        return imageMap;
    }

    // ==========================================
    // 11. TẠO FILE DOCX BLOB HOÀN CHỈNH
    // ==========================================
    async function createDocxBlob({ title, questions, mode = 'questions', options = {} }) {
        if (typeof JSZip === 'undefined') {
            throw new Error('Thư viện JSZip chưa được tải!');
        }

        let questionList = questions;
        if (typeof questionList === 'string') {
            const parseFn = (window.QuestionImporter && window.QuestionImporter.parseLatexExamString) || window.parseLatexExamString;
            if (typeof parseFn === 'function') {
                questionList = parseFn(questionList);
            }
        }
        if (!Array.isArray(questionList)) {
            questionList = [];
        }

        let zip;
        if (typeof DEFAULT_DOCX_BASE64 !== 'undefined' && DEFAULT_DOCX_BASE64) {
            zip = await JSZip.loadAsync(DEFAULT_DOCX_BASE64, { base64: true });
        } else {
            zip = new JSZip();
        }

        const formulaRegistry = new DocxFormulaRegistry();

        // 1. Nạp và xử lý toàn bộ hình ảnh
        const imageMap = await collectAndPrepareImages(questionList, zip);

        // 2. Tạo nội dung document.xml (đồng thời thu thập các công thức MathType)
        const docXml = buildDocumentXml({
            title,
            questions: questionList,
            mode,
            options,
            imageMap,
            formulaRegistry
        });
        zip.file('word/document.xml', docXml);

        // 3. Nếu ở chế độ MathType OLE: nhúng toàn bộ oleObject.bin và image.wmf vào zip
        if (options.formulaMode !== 'omml') {
            formulaRegistry.entries.forEach(entry => {
                zip.file(`word/${entry.oleTarget}`, entry.oleBytes);
            });
            formulaRegistry.wmfRidMap.forEach((val) => {
                zip.file(`word/${val.wmfTarget}`, val.wmfBytes);
            });
        }

        // 4. Cập nhật word/_rels/document.xml.rels
        let relsXml = zip.file('word/_rels/document.xml.rels') ? await zip.file('word/_rels/document.xml.rels').async('text') : '';
        if (relsXml) {
            let extraRels = '';
            const seenImgRids = new Set();
            Object.values(imageMap).forEach(img => {
                if (img && img.rId && !seenImgRids.has(img.rId)) {
                    seenImgRids.add(img.rId);
                    extraRels += `\n  <Relationship Id="${img.rId}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/image_${img.id}.png"/>`;
                }
            });
            if (options.formulaMode !== 'omml') {
                formulaRegistry.wmfRidMap.forEach((val) => {
                    extraRels += `\n  <Relationship Id="${val.wmfRid}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="${val.wmfTarget}"/>`;
                });
                formulaRegistry.entries.forEach(entry => {
                    extraRels += `\n  <Relationship Id="${entry.oleRid}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/oleObject" Target="${entry.oleTarget}"/>`;
                });
            }
            relsXml = relsXml.replace('</Relationships>', extraRels + '\n</Relationships>');
            zip.file('word/_rels/document.xml.rels', relsXml);
        }

        // 5. Cập nhật [Content_Types].xml để Word nhận diện đúng định dạng OLE và WMF
        let ctXml = zip.file('[Content_Types].xml') ? await zip.file('[Content_Types].xml').async('text') : '';
        if (ctXml) {
            let extraDefaults = '';
            if (!ctXml.includes('Extension="bin"')) extraDefaults += '<Default Extension="bin" ContentType="application/vnd.openxmlformats-officedocument.oleObject"/>';
            if (!ctXml.includes('Extension="wmf"')) extraDefaults += '<Default Extension="wmf" ContentType="image/x-wmf"/>';
            if (!ctXml.includes('Extension="png"')) extraDefaults += '<Default Extension="png" ContentType="image/png"/>';
            if (extraDefaults) {
                ctXml = ctXml.replace(/<Types\b([^>]*)>/, '<Types$1>' + extraDefaults);
                zip.file('[Content_Types].xml', ctXml);
            }
        }

        const zipType = (options && options.returnType) ? options.returnType : (typeof Blob !== 'undefined' ? 'blob' : 'uint8array');
        return await zip.generateAsync({ type: zipType, compression: 'DEFLATE' });
    }

    function triggerDownload(blob, filename) {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    function sanitizeFilename(name) {
        return (name || 'De_Thi')
            .replace(/[/\\?%*:|"<>]/g, '_')
            .replace(/\s+/g, '_')
            .trim();
    }

    // ==========================================
    // 11.5. ĐỘNG CƠ XUẤT PYODIDE PYTHON WASM (TeX2MathType Pro)
    // ==========================================
    let pyodideExporterWorker = null;
    let isPyodideExporterReady = false;
    let pyodideInitPromise = null;

    function getPyodideExporterWorker(onProgress) {
        if (pyodideExporterWorker && isPyodideExporterReady) {
            return Promise.resolve(pyodideExporterWorker);
        }
        if (pyodideInitPromise) {
            return pyodideInitPromise;
        }

        pyodideInitPromise = new Promise((resolve, reject) => {
            try {
                if (!pyodideExporterWorker) {
                    pyodideExporterWorker = new Worker("tex2mathtype-worker.js?v=20261016_V6");
                }
                const initTimeout = setTimeout(() => {
                    if (!isPyodideExporterReady) {
                        pyodideInitPromise = null;
                        reject(new Error("Timeout khởi tạo Pyodide (vượt quá 60s)"));
                    }
                }, 60000);

                const initHandler = (e) => {
                    const { type, message, pct, error } = e.data;
                    if (type === "READY") {
                        clearTimeout(initTimeout);
                        isPyodideExporterReady = true;
                        if (onProgress) onProgress(100, "Động cơ Python TeX2MathType Pro đã sẵn sàng!");
                        resolve(pyodideExporterWorker);
                    } else if (type === "PROGRESS") {
                        if (onProgress) onProgress(pct, message);
                    } else if (type === "ERROR" && !isPyodideExporterReady) {
                        clearTimeout(initTimeout);
                        pyodideInitPromise = null;
                        reject(new Error(error || "Không thể khởi tạo Python WebAssembly"));
                    }
                };

                pyodideExporterWorker.addEventListener("message", initHandler);
                pyodideExporterWorker.addEventListener("error", (err) => {
                    clearTimeout(initTimeout);
                    pyodideInitPromise = null;
                    reject(err);
                });
            } catch(e) {
                pyodideInitPromise = null;
                reject(e);
            }
        });

        return pyodideInitPromise;
    }

    function htmlTableToLatexTabular(html) {
        if (!html || !html.includes('<table')) return html;
        return html.replace(/<table[^>]*>([\s\S]*?)<\/table>/gi, function(match, tableBody) {
            const rowMatches = tableBody.match(/<tr[^>]*>([\s\S]*?)<\/tr>/gi);
            if (!rowMatches || rowMatches.length === 0) return '';
            
            const tableRows = [];
            let maxCols = 0;
            for (const r of rowMatches) {
                const cells = [];
                const cellMatches = r.match(/<(?:td|th)[^>]*>([\s\S]*?)<\/(?:td|th)>/gi);
                if (cellMatches) {
                    for (const c of cellMatches) {
                        let cellContent = c.replace(/^<(?:td|th)[^>]*>/i, '').replace(/<\/(?:td|th)>$/i, '').trim();
                        cellContent = cellContent.replace(/<br\s*\/?>/gi, ' ');
                        cellContent = cellContent.replace(/<b>(.*?)<\/b>/gi, '\\textbf{$1}');
                        cellContent = cellContent.replace(/<strong>(.*?)<\/strong>/gi, '\\textbf{$1}');
                        cellContent = cellContent.replace(/<i>(.*?)<\/i>/gi, '\\textit{$1}');
                        cellContent = cellContent.replace(/<em>(.*?)<\/em>/gi, '\\textit{$1}');
                        cellContent = cellContent.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
                        cellContent = cellContent.replace(/<\/?(?:div|span|p)[^>]*>/gi, ' ').trim();
                        cells.push(cellContent);
                    }
                }
                if (cells.length > 0) {
                    tableRows.push(cells);
                    if (cells.length > maxCols) maxCols = cells.length;
                }
            }
            if (tableRows.length === 0 || maxCols === 0) return '';
            
            const colSpec = '|' + Array(maxCols).fill('c|').join('');
            let tex = `\\begin{tabular}{${colSpec}}\n\\hline\n`;
            for (const row of tableRows) {
                while (row.length < maxCols) row.push('');
                tex += row.join(' & ') + ' \\\\\n\\hline\n';
            }
            tex += '\\end{tabular}\n';
            return '\n\n' + tex + '\n\n';
        });
    }

    function cleanHtmlToLatex(text) {
        if (!text) return "";
        let s = String(text);
        s = htmlTableToLatexTabular(s);
        s = s.replace(/<div[^>]*>\s*<img[^>]*src="([^"]+)"[^>]*>\s*<\/div>/gi, '\n\\begin{center}\n\\includegraphics{$1}\n\\end{center}\n');
        s = s.replace(/<img[^>]*src="([^"]+)"[^>]*>/gi, '\n\\begin{center}\n\\includegraphics{$1}\n\\end{center}\n');
        s = s.replace(/<br\s*\/?>/gi, '\n');
        s = s.replace(/<p>([\s\S]*?)<\/p>/gi, '$1\n\n');
        s = s.replace(/<b>(.*?)<\/b>/gi, '\\textbf{$1}');
        s = s.replace(/<strong>(.*?)<\/strong>/gi, '\\textbf{$1}');
        s = s.replace(/<i>(.*?)<\/i>/gi, '\\textit{$1}');
        s = s.replace(/<em>(.*?)<\/em>/gi, '\\textit{$1}');
        s = s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
        s = s.replace(/<\/?(?:div|span|script)[^>]*>/gi, '');
        return s.trim();
    }

    async function exportExamViaPyodide(exam, customOptions = {}) {
        if (!exam) throw new Error('Không có dữ liệu đề thi');
        const questions = exam.questions || [];
        const baseName = sanitizeFilename(customOptions.examTitle || exam.title || 'De_Thi');
        const mode = customOptions.mode || 'questions';

        const btnConfirm = document.getElementById('btnConfirmExportWord');
        const setStatus = (pct, msg) => {
            if (btnConfirm) {
                btnConfirm.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> [${pct}%] ${msg}`;
            }
        };

        setStatus(5, "Đang tải động cơ Python TeX2MathType Pro...");
        const worker = await getPyodideExporterWorker(setStatus);

        setStatus(15, "Đang nạp hình ảnh từ kho Cloudflare R2...");
        // 1. Quét hình ảnh
        const scanImgs = (txt) => {
            if (!txt) return [];
            const res = [];
            const m1 = txt.matchAll(/<img\s+[^>]*src=["']([^"']+)["'][^>]*>/gi);
            for (const m of m1) res.push(m[1]);
            const m2 = txt.matchAll(/\\includegraphics(?:\[.*?\])?\{([^}]+)\}/gi);
            for (const m of m2) res.push(m[1]);
            return res;
        };

        const allSources = [];
        questions.forEach(q => {
            if (q.image) allSources.push(q.image);
            if (q.img) allSources.push(q.img);
            if (q.imageUrl) allSources.push(q.imageUrl);
            if (q.image_url) allSources.push(q.image_url);
            if (Array.isArray(q.images)) allSources.push(...q.images);
            allSources.push(...scanImgs(q.content));
            allSources.push(...scanImgs(q.solution || q.explain));
            (q.options || []).forEach(opt => {
                if (typeof opt === 'object') {
                    if (opt.image) allSources.push(opt.image);
                    if (opt.img) allSources.push(opt.img);
                    allSources.push(...scanImgs(opt.text));
                } else {
                    allSources.push(...scanImgs(opt));
                }
            });
            (q.statements || []).forEach(st => {
                if (typeof st === 'object') {
                    if (st.image) allSources.push(st.image);
                    if (st.img) allSources.push(st.img);
                    allSources.push(...scanImgs(st.text || st.content));
                } else {
                    allSources.push(...scanImgs(st));
                }
            });
        });

        const uniqueSources = Array.from(new Set(allSources.filter(Boolean)));
        const imagesList = [];
        const imageMap = {};
        let imgIdx = 0;

        for (const src of uniqueSources) {
            try {
                const bytes = await fetchImageBytes(src);
                if (bytes && bytes.length > 0) {
                    imgIdx++;
                    const fname = `exam_img_${imgIdx}.png`;
                    imageMap[src] = fname;
                    imagesList.push({ filename: fname, data: bytes });
                }
            } catch(e) {
                console.warn('[PyodideExport] Không thể nạp ảnh:', src, e);
            }
        }

        setStatus(30, "Đang chuẩn hóa đề thi sang LaTeX...");
        
        // Phân loại câu hỏi thành 4 phần chuẩn Bộ GD&ĐT 2025
        const p1List = [];
        const p2List = [];
        const p3List = [];
        const p4List = [];

        questions.forEach((q, idx) => {
            const type = (q.type || '').toLowerCase();
            if (type === 'tf' || type === 'true_false' || (Array.isArray(q.statements) && q.statements.length > 0)) {
                p2List.push({ ...q, globalIdx: idx + 1 });
            } else if (type === 'short' || type === 'tl_short' || (q.answer !== undefined && q.answer !== null && !Array.isArray(q.options) && String(q.answer).trim() !== '')) {
                p3List.push({ ...q, globalIdx: idx + 1 });
            } else if (type === 'essay' || type === 'tl') {
                p4List.push({ ...q, globalIdx: idx + 1 });
            } else {
                p1List.push({ ...q, globalIdx: idx + 1 });
            }
        });

        let currentRomanPy = 1;
        const romanNumeralsPy = ['I', 'II', 'III', 'IV'];

        const formatQuestionLatex = (q) => {
            let res = '';
            let content = q.content || '';
            for (const [sUrl, fName] of Object.entries(imageMap)) {
                if (content.includes(sUrl)) content = content.split(sUrl).join(fName);
            }
            content = cleanHtmlToLatex(content);
            const env = q.env || (q.type === 'essay' || q.type === 'tl' ? 'bt' : 'ex');
            const cccd = q.cccd || q.bankId || q.id || '';
            
            res += `\\begin{${env}}[${cccd}]\n${content}\n`;

            const qCandidates = [q.image, q.img, q.imageUrl, q.image_url];
            if (Array.isArray(q.images)) qCandidates.push(...q.images);
            qCandidates.forEach(cand => {
                if (cand && imageMap[cand] && !content.includes(imageMap[cand])) {
                    res += `\\begin{center}\n\\includegraphics{${imageMap[cand]}}\n\\end{center}\n`;
                }
            });

            if (q.type === 'tf' || (Array.isArray(q.statements) && q.statements.length > 0)) {
                const stmts = Array.isArray(q.statements) ? q.statements : q.options;
                const tfItems = (stmts || []).map((st, sIdx) => {
                    let stText = typeof st === 'object' ? (st.content || st.text || '') : st;
                    for (const [sUrl, fName] of Object.entries(imageMap)) {
                        if (stText.includes(sUrl)) stText = stText.split(sUrl).join(fName);
                    }
                    stText = cleanHtmlToLatex(stText);
                    const isTrue = (getTfAnswerChar(q, sIdx) === 'Đ');
                    return `\t{${isTrue ? '\\True ' : ''}${stText}}`;
                }).join('\n');
                res += `\\choiceTF\n${tfItems}\n`;
            } else if (Array.isArray(q.options) && q.options.length > 0) {
                const correctIdx = getChoiceCorrectIndex(q);
                const choiceItems = q.options.map((opt, i) => {
                    let optText = typeof opt === 'object' ? (opt.text || '') : opt;
                    for (const [sUrl, fName] of Object.entries(imageMap)) {
                        if (optText.includes(sUrl)) optText = optText.split(sUrl).join(fName);
                    }
                    optText = cleanHtmlToLatex(optText);
                    const isCorrect = (i === correctIdx);
                    return `\t{${isCorrect ? '\\True ' : ''}${optText}}`;
                }).join('\n');
                res += `\\choice\n${choiceItems}\n`;
            } else if (q.type === 'short' || (q.answer !== undefined && q.answer !== null && String(q.answer).trim() !== '')) {
                const ans = getShortAnswerText(q);
                if (ans) {
                    const ansLatex = formatShortAnswerForLatex(ans);
                    if (customOptions.underlineCorrect || mode === 'full') {
                        res += `\\textbf{Đáp án: }${ansLatex}\n\n`;
                    }
                }
            }

            if (q.solution || q.explain) {
                let sol = q.solution || q.explain || '';
                for (const [sUrl, fName] of Object.entries(imageMap)) {
                    if (sol.includes(sUrl)) sol = sol.split(sUrl).join(fName);
                }
                sol = cleanHtmlToLatex(sol);
                res += `\\loigiai{\n${sol}\n}\n`;
            }

            res += `\\end{${env}}\n\n`;
            return res;
        };

        let fullLatex = '';
        if (p1List.length > 0) {
            fullLatex += `\n\\textbf{PHẦN ${romanNumeralsPy[currentRomanPy - 1]}. Câu trắc nghiệm nhiều phương án lựa chọn. Thí sinh trả lời từ câu 1 đến câu ${p1List.length}. Mỗi câu hỏi thí sinh chỉ chọn một phương án.}\n\n`;
            currentRomanPy++;
            p1List.forEach(q => { fullLatex += formatQuestionLatex(q); });
        }
        if (p2List.length > 0) {
            fullLatex += `\n\\textbf{PHẦN ${romanNumeralsPy[currentRomanPy - 1]}. Câu trắc nghiệm đúng sai. Thí sinh trả lời từ câu 1 đến câu ${p2List.length}. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.}\n\n`;
            currentRomanPy++;
            p2List.forEach(q => { fullLatex += formatQuestionLatex(q); });
        }
        if (p3List.length > 0) {
            fullLatex += `\n\\textbf{PHẦN ${romanNumeralsPy[currentRomanPy - 1]}. Câu trắc nghiệm trả lời ngắn. Thí sinh trả lời từ câu 1 đến câu ${p3List.length}.}\n\n`;
            currentRomanPy++;
            p3List.forEach(q => { fullLatex += formatQuestionLatex(q); });
        }
        if (p4List.length > 0) {
            fullLatex += `\n\\textbf{PHẦN ${romanNumeralsPy[currentRomanPy - 1]}. Tự luận. Thí sinh trình bày chi tiết lời giải từ câu 1 đến câu ${p4List.length}.}\n\n`;
            currentRomanPy++;
            p4List.forEach(q => { fullLatex += formatQuestionLatex(q); });
        }

        // Bổ sung bảng đáp án tổng hợp ở cuối đề (Pyodide LaTeX)
        if (customOptions.includeAnswerTable && (p1List.length > 0 || p2List.length > 0 || p3List.length > 0)) {
            fullLatex += `\n\n\\begin{center}\n\\textbf{BẢNG ĐÁP ÁN TỔNG HỢP}\n\\end{center}\n\n`;
            if (p1List.length > 0) {
                fullLatex += `\\textbf{Phần I: Trắc nghiệm 4 phương án}\n\n`;
                const colsPerRow = 10;
                const rows = Math.ceil(p1List.length / colsPerRow);
                for (let r = 0; r < rows; r++) {
                    const rQuestions = p1List.slice(r * colsPerRow, (r + 1) * colsPerRow);
                    const colAlign = '|' + rQuestions.map(() => 'c|').join('');
                    fullLatex += `\\begin{tabular}{${colAlign}}\n\\hline\n`;
                    fullLatex += rQuestions.map((_, i) => `\\textbf{Câu ${r * colsPerRow + i + 1}}`).join(' & ') + ' \\\\\n\\hline\n';
                    fullLatex += rQuestions.map(q => `\\textbf{${getChoiceCorrectLetter(q)}}`).join(' & ') + ' \\\\\n\\hline\n';
                    fullLatex += `\\end{tabular}\n\n`;
                }
            }
            if (p2List.length > 0) {
                fullLatex += `\\textbf{Phần II: Đáp án Đúng/Sai}\n\n`;
                fullLatex += `\\begin{tabular}{|c|c|c|c|c|}\n\\hline\n`;
                fullLatex += `\\textbf{Câu} & \\textbf{Ý a)} & \\textbf{Ý b)} & \\textbf{Ý c)} & \\textbf{Ý d)} \\\\\n\\hline\n`;
                p2List.forEach((q, idx) => {
                    const a = getTfAnswerChar(q, 0);
                    const b = getTfAnswerChar(q, 1);
                    const c = getTfAnswerChar(q, 2);
                    const d = getTfAnswerChar(q, 3);
                    fullLatex += `\\textbf{Câu ${idx + 1}} & \\textbf{${a}} & \\textbf{${b}} & \\textbf{${c}} & \\textbf{${d}} \\\\\n\\hline\n`;
                });
                fullLatex += `\\end{tabular}\n\n`;
            }
            if (p3List.length > 0) {
                fullLatex += `\\textbf{Phần III: Đáp án Trả lời ngắn}\n\n`;
                const colsPerRow = 6;
                const rows = Math.ceil(p3List.length / colsPerRow);
                for (let r = 0; r < rows; r++) {
                    const rQuestions = p3List.slice(r * colsPerRow, (r + 1) * colsPerRow);
                    const colAlign = '|' + rQuestions.map(() => 'c|').join('');
                    fullLatex += `\\begin{tabular}{${colAlign}}\n\\hline\n`;
                    fullLatex += rQuestions.map((_, i) => `\\textbf{Câu ${r * colsPerRow + i + 1}}`).join(' & ') + ' \\\\\n\\hline\n';
                    fullLatex += rQuestions.map(q => formatShortAnswerForLatex(getShortAnswerText(q))).join(' & ') + ' \\\\\n\\hline\n';
                    fullLatex += `\\end{tabular}\n\n`;
                }
            }
        }

        setStatus(40, "Đang chuyển đổi MathType OLE trong Python Wasm...");

        return new Promise((resolve, reject) => {
            const reqId = Date.now();
            const messageHandler = function (e) {
                const { type, message, pct, files, error, id } = e.data;
                if (id && id !== reqId) return;

                if (type === 'PROGRESS') {
                    setStatus(pct, message);
                } else if (type === 'SUCCESS') {
                    worker.removeEventListener('message', messageHandler);
                    setStatus(100, "Hoàn tất! Đang tải file Word...");
                    files.forEach(f => {
                        const blob = new Blob([f.data], {
                            type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
                        });
                        let outName = f.filename;
                        if (mode === 'questions' && (!outName.includes('De_Bai') && !outName.includes('De_Thi'))) {
                            outName = `${baseName}_De_Bai.docx`;
                        } else if (mode === 'full' && (!outName.includes('Loi_Giai'))) {
                            outName = `${baseName}_De_Va_Loi_Giai.docx`;
                        } else if (files.length === 1 && !outName.includes(baseName)) {
                            outName = `${baseName}_${f.filename}`;
                        }
                        triggerDownload(blob, outName);
                    });
                    resolve(files);
                } else if (type === 'ERROR') {
                    worker.removeEventListener('message', messageHandler);
                    reject(new Error(error));
                }
            };

            const headerConfig = {
                style: customOptions.headerStyle || 'standard_gov',
                agency: customOptions.agencyName || 'SỞ GD&ĐT HÀ NỘI',
                school: customOptions.schoolName || 'TRƯỜNG THPT TRẦN QUANG KHẢI',
                exam_type: customOptions.examType || '(ĐỀ CHÍNH THỨC)',
                title: customOptions.examTitle || exam.title || 'ĐỀ THI',
                subject: customOptions.subject || 'TOÁN HỌC',
                grade: customOptions.grade || '9',
                duration: customOptions.duration || 90,
                exam_code: customOptions.examCode || '1001',
                candidate_info: customOptions.includeCandidateInfo !== false,
                underline_correct: customOptions.underlineCorrect === true
            };

            worker.addEventListener('message', messageHandler);
            worker.postMessage({
                action: 'CONVERT_TEX',
                id: reqId,
                payload: {
                    text: fullLatex,
                    standard: customOptions.standard || 'btn_group',
                    mode: mode,
                    base_pt: 11.0,
                    images: imagesList,
                    header_config: headerConfig
                }
            });
        });
    }

    // ==========================================
    // 12. HÀM XUẤT ĐỀ THI RA FILE WORD
    // ==========================================
    async function exportExamToWord(exam, customOptions = {}) {
        if (!exam) throw new Error('Không có dữ liệu đề thi');
        const questions = exam.questions || [];
        const baseName = sanitizeFilename(customOptions.examTitle || exam.title || 'De_Thi');
        const mode = customOptions.mode || 'questions';
        const formulaMode = customOptions.formulaMode || 'mathtype';

        // 1. Nếu chọn MathType: Ưu tiên xử lý bằng Pyodide Python WebAssembly (chuẩn TeX2MathType Pro)
        if (formulaMode === 'mathtype') {
            try {
                return await exportExamViaPyodide(exam, customOptions);
            } catch (pyErr) {
                console.warn('[MathType Exporter] Pyodide gặp sự cố, tự động fallback sang bộ tạo tích hợp:', pyErr);
                // Fallback nếu người dùng offline hoặc CDN bị lỗi
            }
        }

        // 2. Chế độ OMML hoặc fallback built-in docx blob generator
        if (mode === 'both') {
            const blobQ = await createDocxBlob({
                title: customOptions.examTitle || exam.title || 'Đề thi',
                questions: questions,
                mode: 'questions',
                options: customOptions
            });
            triggerDownload(blobQ, `${baseName}_De_Bai.docx`);

            await new Promise(r => setTimeout(r, 600));

            const blobF = await createDocxBlob({
                title: customOptions.examTitle || exam.title || 'Đề thi',
                questions: questions,
                mode: 'full',
                options: customOptions
            });
            triggerDownload(blobF, `${baseName}_De_Va_Loi_Giai.docx`);
        } else if (mode === 'full') {
            const blob = await createDocxBlob({
                title: customOptions.examTitle || exam.title || 'Đề thi',
                questions: questions,
                mode: 'full',
                options: customOptions
            });
            triggerDownload(blob, `${baseName}_De_Va_Loi_Giai.docx`);
        } else {
            const blob = await createDocxBlob({
                title: customOptions.examTitle || exam.title || 'Đề thi',
                questions: questions,
                mode: 'questions',
                options: customOptions
            });
            triggerDownload(blob, `${baseName}_De_Bai.docx`);
        }
    }

